// cfg override (grep ASSUMPTION) so non-matching repos write config, not code.
//
// Usage:
//   node package-build.mjs --config .design-sync/config.json \
//     --node-modules ./node_modules \
//     --entry ./dist/index.js \
//     --storybook-static ./storybook-static \
