  if (i < 0) return dflt;
  return argv[i + 1];
}
const CONFIG_PATH = flag('config');

const NON_IMPL_RX = /\.(stories|test|spec)\./;
const SRC_IMPL_RX = /\.(tsx|jsx)$/;
