        Whole fight
      </button>

      <button key="live" onClick={() => setScope('live')} className={'pill' + (scope === 'live' ? ' active' : '')} style={{ borderRadius: 6, display: 'flex', alignItems: 'center', gap: 5 }}>
        {scope === 'live' && (
          <span style={{
            width: 6,
            height: 6,
            borderRadius: '50%',
            background: 'var(--text-primary)',
            display: 'inline-block',
