// Records every /api response the real frontend makes on each screen, so the
// screens bundle can replay them offline. Needs the local backend (DEV_LOGIN=1)
// on :8000 and `npm run dev --prefix frontend` on :5173.
// Run from the repo root: node .design-sync/screens/record.mjs
import { writeFileSync, mkdirSync } from 'node:fs';
import { createRequire } from 'node:module';
import { SCREENS } from './screens.config.mjs';

const require = createRequire(new URL('../../.ds-sync/package.json', import.meta.url));
const { chromium } = require('playwright');
const APP = 'http://localhost:5173';
const OUT = new URL('../.cache/screens/', import.meta.url);
mkdirSync(OUT, { recursive: true });

const browser = await chromium.launch();
const fixtures = {};
for (const s of SCREENS) {
  if (s.signedOut) continue;
  const ctx = await browser.newContext({ viewport: { width: 1440, height: 900 } });
  const page = await ctx.newPage();
  await page.goto(`${APP}/api/auth/dev-login?role=${s.role ?? 'admin'}`);
  // Never stream the real video or hold the SSE open while recording.
  await page.route(/\/api\/fights\/\d+\/video|\/api\/fights\/stream/, r => r.abort());
  page.on('response', async res => {
    const u = new URL(res.url());
    if (!u.pathname.startsWith('/api/') || res.request().method() !== 'GET') return;
    if (/\/frames\/$/.test(u.pathname) && !u.search) return; // recorded windowed below
    try { fixtures[u.pathname + u.search] = { status: res.status(), body: await res.json() }; } catch { /* non-JSON */ }
  });
  await page.goto(APP + s.path, { waitUntil: 'load' });
  await page.waitForTimeout(4000);
  if (s.frames) {
    const { fightId, start, end } = s.frames;
    const r = await page.request.get(`${APP}/api/fights/${fightId}/frames/?start_frame=${start}&end_frame=${end}`);
    fixtures[`/api/fights/${fightId}/frames/`] = { status: 200, body: await r.json() };
  }
  console.log(`recorded ${s.name}`);
  await ctx.close();
}
await browser.close();
writeFileSync(new URL('fixtures.json', OUT), JSON.stringify(fixtures));
console.log(`${Object.keys(fixtures).length} responses → .design-sync/.cache/screens/fixtures.json`);
EOF
